(() => {
  'use strict';
  const D=OverviewDemo.data,U=OverviewDemo.utilities,M=OverviewModel,V=OverviewCharts,S=OverviewSpec;
  const {esc,number}=V;
  const page=document.body.dataset.overviewPage;
  const pages={
    kpi:['KPI Dashboard','kpi-dashboard.html'],content:['Content Performance','content-performance-dashboard.html'],users:['End User Statistics','end-user-stats-dashboard.html'],agents:['Agency Statistics','agent-stats-dashboard.html'],properties:['Property Statistics','property-stats-dashboard.html'],ads:['Revenue & Ad Performance','ad-performance-dashboard.html'],market:['Market Analysis','market-analysis-dashboard.html'],cross:['Cross Analysis','cross-analysis-dashboard.html'],league:['Agency League','agent-league-dashboard.html'],marketing:['CRM Marketing','marketing-dashboard.html'],reports:['Report Management','report-management-dashboard.html'],financial:['Financial Reports','financial-reports-dashboard.html'],sales:['Sales Reports','sales-reports-dashboard.html']
  };
  const storage={get(key,fallback){try{return JSON.parse(localStorage.getItem('yuushi.overview.'+key))??fallback;}catch{return fallback;}},set(key,value){try{localStorage.setItem('yuushi.overview.'+key,JSON.stringify(value));}catch{}}};
  const defaults={transaction:'All',groups:[],subtypes:[],unit:'Monthly',comparison:'Previous Month',start:U.addDays(D.today,-29),end:D.today,compareStart:'',compareEnd:'',prefectures:[],cities:[],line:'',stations:[],walk:'',structures:[],floorPlans:[],ageMin:'',ageMax:'',areaMin:'',areaMax:'',priceMin:'',priceMax:'',membership:'All',conversion:'Inquiries'};
  let filtersApplied=Boolean(storage.get('filters',null));
  let filters={...defaults,...storage.get('filters',{})};
  let enabledFraud={...Object.fromEntries(S.alerts.filter(a=>a.fraud).map(a=>[a.id,true])),...storage.get('fraudKpi',{})};
  let targets=storage.get('targets',[]),savedReports=storage.get('reportShortcuts',[]),schedules=storage.get('reportSchedules',[]);
  const results=new Map(),choices=new Map();
  const select=(id,label,values,multiple=false)=>`<label class="field">${esc(label)}<select id="${id}" name="${id}" ${multiple?'multiple':''}>${values.map(v=>{const [value,text]=Array.isArray(v)?v:[v,v];return `<option value="${esc(value)}">${esc(text)}</option>`;}).join('')}</select></label>`;
  const input=(id,label,type='date')=>`<label class="field">${esc(label)}<input id="${id}" name="${id}" type="${type}" ${type==='number'?'min="0" step="any"':''}></label>`;
  const headings={content:[35,40],users:[42,60],agents:[69,84],properties:[91,105],ads:[107,118],market:[120,128],cross:[130,137],league:[80,80],marketing:[137,137]};
  const metricsForPage=()=>{const range=headings[page];return range?S.metrics.filter(s=>!s.outOfScope&&s.definition&&s.row>=range[0]&&s.row<=range[1]):[];};
  function toast(message){const el=document.getElementById('toast');el.textContent=message;el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,4500);}
  function downloadCSV(name,columns,rows){toast('CSV export prepared for demo. '+rows.length+' rows · '+name);}
  window.mockExportContext=b=>{const r=results.get(b.dataset.export);return r?r.rows.length+' filtered rows.':'Current dashboard filters applied.';};
  function exportResult(id,format='csv'){const r=results.get(id);if(!r||r.unavailable)return;toast((format==='xlsx'?'Excel':'CSV')+' export prepared for demo. '+r.rows.length+' filtered rows.');}
  window.mockExportPrepare=(button,format)=>exportResult(button.dataset.export,format);
  function filterMarkup(){return `<form class="filters" id="overviewFilters"><div class="filters-summary"><strong>Analytics filters</strong><p id="filterSummary"></p><div class="actions"><button class="btn" type="button" id="resetFilters">Reset</button><button class="btn primary" type="submit">Apply filters</button></div></div><div class="filter-primary">${select('transaction','1 · Transaction type',['All','For Sale','For Rent','New Development'])}${select('unit','3 · Period unit',['Daily','Weekly','Monthly','Quarterly','Yearly','Custom'])}${input('start','Start date')}${input('end','End date')}${select('comparison','4 · Compare with',['None','Previous Day','Previous Month','Previous Quarter','Previous Year','Custom'])}${select('membership','8 · User type',[['All','All'],['Members','Registered Members'],['Non-Members','Guests / Non-Members'],['Members vs Non-Members','Members vs Guests']])}</div><div class="pair" id="customComparison" hidden>${input('compareStart','Comparison start')}${input('compareEnd','Comparison end')}</div><details><summary>Property, area and station filters</summary><p>Use Ctrl / Command to select multiple values. Leave a multi-select empty to include all values.</p><div class="filter-grid"><fieldset class="field-group"><legend>2 · Property group and sub-type</legend>${select('groups','Property groups',[],true)}${select('subtypes','Sub-types',[],true)}</fieldset><fieldset class="field-group"><legend>5 · Area</legend>${select('prefectures','Prefectures',[...new Set(D.places.map(p=>p[0]))],true)}${select('cities','City / Ward / Town',[],true)}</fieldset><fieldset class="field-group"><legend>6 · Station and railway</legend>${select('line','Railway line',[['','All lines'],...[...new Set(D.places.map(p=>p[2]))]])}${select('stations','Stations',[],true)}${select('walk','Maximum walking time',[['','Any'],['5','5 minutes'],['10','10 minutes'],['15','15 minutes'],['30','30 minutes']])}</fieldset><fieldset class="field-group"><legend>7 · Property attributes</legend>${select('structures','Building structure',D.structures,true)}${select('floorPlans','Floor plan',['Studio','1LDK','2LDK','3LDK','4LDK+'],true)}</fieldset><fieldset class="field-group"><legend>7 · Age and floor area</legend><div class="pair">${input('ageMin','Minimum age (years)','number')}${input('ageMax','Maximum age (years)','number')}${input('areaMin','Minimum floor area (m²)','number')}${input('areaMax','Maximum floor area (m²)','number')}</div></fieldset><fieldset class="field-group"><legend>7 · Price</legend><p id="priceBasis" class="muted"></p><div class="pair">${input('priceMin','Minimum price (JPY)','number')}${input('priceMax','Maximum price (JPY)','number')}</div>${select('conversion','CPA conversion',['Inquiries','Closings'])}</fieldset></div></details><p class="error" id="filterError" role="alert" hidden></p></form>`;}
  function readFilters(){const next={};Object.keys(defaults).forEach(key=>{const el=document.getElementById(key);if(el)next[key]=el.multiple?[...el.selectedOptions].map(o=>o.value):el.value;});return {...filters,...next};}
  function setSelectOptions(id,values,selected=[]){const el=document.getElementById(id);el.innerHTML=values.map(v=>{const [value,label]=Array.isArray(v)?v:[v,v];return `<option value="${esc(value)}" ${selected.includes(value)?'selected':''}>${esc(label)}</option>`;}).join('');}
  function updateDependentFilters(){const current=readFilters();const availableGroups=Object.entries(D.groups).filter(([,g])=>current.transaction==='All'||g.transaction===current.transaction);setSelectOptions('groups',availableGroups.map(([id,g])=>[id,g.label]),current.groups);const selected=[...document.getElementById('groups').selectedOptions].map(o=>o.value);setSelectOptions('subtypes',[...new Set(availableGroups.filter(([id])=>!selected.length||selected.includes(id)).flatMap(([,g])=>g.types))],current.subtypes);setSelectOptions('cities',[...new Set(D.places.filter(p=>!current.prefectures.length||current.prefectures.includes(p[0])).map(p=>p[1]))],current.cities);setSelectOptions('stations',[...new Set(D.places.filter(p=>!current.line||p[2]===current.line).map(p=>p[3]))],current.stations);document.getElementById('customComparison').hidden=current.comparison!=='Custom';document.getElementById('priceBasis').textContent=current.transaction==='For Rent'?'Monthly rent (JPY/month)':current.transaction==='New Development'?'Unit price (JPY)':'Sale price (JPY). Select For Rent for monthly rent.';}
  function restoreFilters(){Object.entries(filters).forEach(([key,value])=>{const el=document.getElementById(key);if(el&&!el.multiple)el.value=value;});for(const key of ['prefectures','structures','floorPlans']){const el=document.getElementById(key);[...el.options].forEach(o=>o.selected=filters[key]?.includes(o.value));}updateDependentFilters();for(const key of ['groups','subtypes','cities','stations']){const el=document.getElementById(key);[...el.options].forEach(o=>o.selected=filters[key]?.includes(o.value));}updateDependentFilters();}
  function validateFilters(f){if(!f.start||!f.end||f.start>f.end)return 'Choose a valid start and end date.';if(f.end>D.today)return 'The end date cannot be after today.';if(f.comparison==='Custom'&&(!f.compareStart||!f.compareEnd||f.compareStart>f.compareEnd))return 'Choose a valid comparison period.';for(const pair of [['ageMin','ageMax'],['areaMin','areaMax'],['priceMin','priceMax']])if(f[pair[0]]&&f[pair[1]]&&Number(f[pair[0]])>Number(f[pair[1]]))return 'A minimum value cannot exceed its maximum.';return '';}
  function previousFilters(f){if(f.comparison==='None')return null;if(f.comparison==='Custom')return {...f,start:f.compareStart,end:f.compareEnd};const months={'Previous Month':-1,'Previous Quarter':-3,'Previous Year':-12};return {...f,start:f.comparison==='Previous Day'?U.addDays(f.start,-1):M.shiftMonth(f.start,months[f.comparison]),end:f.comparison==='Previous Day'?U.addDays(f.end,-1):M.shiftMonth(f.end,months[f.comparison])};}
  function metricFilters(spec){const choice=choices.get(spec.id)||{};const breakdownDefaults={r35:'section',r46:'country',r47:'composition',r58:'country',r74:'agentId',r83:'prefecture',r53:'subtype',r82:'prefecture',r84:'location',r125:'structure'};const base=page==='kpi'?{...defaults,start:spec.id==='r28'?M.shiftMonth(M.monthStart(D.today),-11):U.addDays(D.today,-29),end:D.today,unit:spec.id==='r28'?'Monthly':'Daily',comparison:'None'}:spec.id==='r54'&&!filtersApplied?{...filters,start:M.shiftMonth(M.monthStart(D.today),-11),end:D.today,unit:'Monthly'}:filters;return {...base,breakdown:breakdownDefaults[spec.id],...choice};}
  function comparisonText(spec,result){const prev=previousFilters(metricFilters(spec));if(!prev||spec.id==='r56')return '';try{const previous=M.metric(spec,prev);const c=result.columns[0];const current=['r43','r44','r55','r70'].includes(spec.id)?result.rows.at(-1)?.[c.key]||0:M.sum(result.rows,c.key),old=['r43','r44','r55','r70'].includes(spec.id)?previous.rows.at(-1)?.[c.key]||0:M.sum(previous.rows,c.key);if(c.unit==='%'||/price|seconds|cpa|days|rating|response/i.test(c.key))return 'Comparison period: '+prev.start+' – '+prev.end+' · see comparison table';return `${number(current,c.unit)} vs ${number(old,c.unit)} · ${old?((current-old)/old*100).toFixed(1)+'%':'No comparison baseline'}`;}catch{return '';}}
  const metricTitleOverrides={
    r55:'Inactive Clients 30+ Days',
    r107:'Platform CPA',
    r112:'Agency Subscription Cost per Conversion',
    r113:'Agency Ad Cost per Conversion by Ad Type',
    r114:'Agency Ad Cost per Conversion by Placement',
    r115:'Paid Ad IMP / View / Click / CV / CVR'
  };
  const metricTitle=spec=>metricTitleOverrides[spec.id]||spec.title;
  function metricDescription(spec,result){
    const description=(result.note||spec.definition||'').trim();
    const calculation=(spec.id==='r56'
      ?'Withdrawals are explicit account withdrawals only. Inactivity is not counted as withdrawal.'
      :spec.id==='r55'
        ?'Analytics segment: active Customer accounts with no recorded login/activity for at least 30 days. Long-term Inactive (90+ days) and Dormant (180+ days) remain separate system-alert states.'
        :(spec.calculation||'')).trim();
    if(!calculation||description.toLowerCase().includes(calculation.toLowerCase()))return description;
    const sentence=text=>/[.!?]$/.test(text)?text:text+'.';
    return `${sentence(description)} ${sentence(calculation)}`;
  }
  function metricControls(spec){if(spec.id==='r54'){const selected=choices.get(spec.id)?.series||['sessions','views','clicks','saves','inquiries','deals'];return '<div class="inline-fields" aria-label="Visible funnel series">'+[['sessions','Sessions'],['views','Property Views'],['clicks','Property Clicks'],['saves','Keep / Saves'],['inquiries','Property Inquiries'],['deals','Agency-recorded Deals']].map(([key,label])=>`<label class="muted"><input type="checkbox" data-series="${spec.id}" value="${key}" ${selected.includes(key)?'checked':''}> ${label}</label>`).join('')+'</div>';}if(spec.id==='r125'){const choice=metricFilters(spec);return `<div class="inline-fields"><label class="muted">Attribute <select data-breakdown="r125">${[['structure','Building Structure'],['floorPlan','Floor Plan'],['age','Building Age Range'],['floorArea','Floor Area Range'],['price','Price Range']].map(([key,label])=>`<option value="${key}" ${choice.breakdown===key?'selected':''}>${label}</option>`).join('')}</select></label><label class="muted">Rank by <select data-rank-by="r125">${[['impressions','Standard Listing Impressions'],['views','Property Views'],['clicks','Property Clicks'],['saves','Keep / Saves'],['inquiries','Property Inquiries']].map(([key,label])=>`<option value="${key}" ${(choice.rankBy||'impressions')===key?'selected':''}>${label}</option>`).join('')}</select></label></div>`;}let options=null;if(spec.id==='r35')options=[['section','Site sections'],['prefecture','Area Guides by prefecture'],['city','Area Guides by neighborhood']];if(spec.id==='r83')options=[['prefecture','Agency area'],['subtype','Supported property types']];if(spec.id==='r137')options=[['channel','Delivery channel'],['campaign','Delivery campaign']];if(spec.id==='r74')options=[['agentId','Per Agency'],['prefecture','Agency location'],['subtype','Property type']];if(spec.id==='r58')options=[['country','Country totals'],['customerId','Messages per End User']];if(spec.id==='r46')options=[['country','Country of residence'],['nationality','Nationality']];if(['r53','r82'].includes(spec.id))options=[['subtype','Property type'],['prefecture','Prefecture'],['city','City / Ward'],['station','Station'],['floorPlan','Floor plan / bedrooms'],['floorArea','Floor area'],['price','Price'],['structure','Structure'],['age','Building age']];if(spec.id==='r84')options=[['location','Property location'],['subtype','Property type']];if(spec.id==='r47')options=[['composition','Session composition and registration rate'],['totals','Behavior totals'],['section','Page type'],['transaction','Transaction type'],['group','Property group'],['city','Area / saved property interest'],['propertyId','Most saved properties'],['subtype','Search property type'],['floorPlan','Search bedrooms'],['price','Search price range'],['age','Search building age'],['exitSection','Exit pages'],['funnel','Member / guest funnel']];return options?`<div class="inline-fields"><label class="muted">Breakdown <select data-breakdown="${spec.id}">${options.map(([key,label])=>`<option value="${key}" ${(metricFilters(spec).breakdown||options[0][0])===key?'selected':''}>${label}</option>`).join('')}</select></label></div>`:'';}
  function chartCard(spec){const title=metricTitle(spec);let result;try{result=M.metric(spec,metricFilters(spec));}catch(error){console.error(error);return `<article class="card chart-card" data-metric="${spec.id}"><h3>${esc(title)}</h3><p class="error">This metric could not be calculated. Please refresh.</p></article>`;}results.set(spec.id,result);if(result.unavailable)return `<article class="card chart-card wide" id="metric-${spec.id}" data-metric="${spec.id}"><div class="chart-heading"><h3>${esc(title)}</h3><span class="badge amber">Source not ready</span></div><div class="notice"><strong>Requires analytics instrumentation / operational data source.</strong><br>${esc(result.note||'No validated platform data lineage is registered for this metric yet.')}</div></article>`;const selected=choices.get(spec.id)?.measure;const previous=previousFilters(metricFilters(spec));let comparison='';if(previous&&spec.id!=='r56'){try{comparison=`<details><summary>Comparison data · ${esc(previous.start)} – ${esc(previous.end)}</summary><div data-comparison-table>${V.table(M.metric(spec,previous))}</div></details>`;}catch{}}
    return `<article class="card chart-card ${result.kind==='table'||['r47','r56','r128'].includes(spec.id)?'wide':''}" id="metric-${spec.id}" data-metric="${spec.id}"><div class="chart-heading"><h3>${esc(title)}</h3><span class="badge">${esc(spec.id==='r56'?'Monthly · 12 months':metricFilters(spec).unit)}</span></div><div class="chart-subtitle"><strong>Description:</strong> ${esc(metricDescription(spec,result))}</div>${['r42','r43','r44','r46','r48','r55','r56','r69','r70','r71','r73','r81'].includes(spec.id)?'<p class="muted">Account metric: period and account area filters apply; property attributes do not apply.</p>':''}${metricControls(spec)}${spec.id==='r125'?'':`<div class="inline-fields" style="margin:8px 0"><label class="muted">Measure <select data-measure="${spec.id}"><option value="">${result.kind==='line'||result.kind==='stacked'?'Compatible series':'Primary measure'}</option>${result.columns.map(c=>`<option value="${esc(c.key)}" ${selected===c.key?'selected':''}>${esc(c.label)}</option>`).join('')}</select></label></div>`}<div class="chart-wrap">${choices.get(spec.id)?.series?.length===0&&!selected?'<div class="empty">Select a funnel series to display.</div>':V.render(!selected&&choices.get(spec.id)?.series?{...result,columns:result.columns.filter(c=>choices.get(spec.id).series.includes(c.key))}:result,selected)}</div>${result.kind==='table'?'':`<details><summary>View data · ${result.rows.length} rows</summary>${V.table(result)}</details>`}${comparison}<div class="chart-footer"><span class="change">${esc(comparisonText(spec,result))}</span><button class="btn" type="button" data-export="${spec.id}">Export</button></div></article>`;
  }
  function renderAnalytics(){results.clear();const metrics=metricsForPage();document.getElementById('filterSummary').textContent=filters.start+' – '+filters.end+' · '+filters.transaction+' · '+filters.membership;document.getElementById('mainContent').innerHTML=`<div class="section-heading"><h2>${esc(pages[page][0])}</h2><span class="chart-count">${metrics.length} metrics</span></div><div class="section-links">${metrics.map(s=>`<a href="#metric-${s.id}">${esc(metricTitle(s))}</a>`).join('')}</div><div class="chart-grid">${metrics.map(chartCard).join('')}</div>`;}
  function kcard(label,value,note='',klass=''){return `<div class="card ${klass}"><div class="metric-label">${esc(label)}</div><div class="metric-value">${value}</div><div class="muted">${esc(note)}</div></div>`;}
  function renderKpi(){
    results.clear();
    const norm=value=>String(value||'').trim().toLowerCase().replace(/\s+/g,'_');
    const unprocessedReports=(D.reports||[]).filter(r=>['awaiting_agency_response','pending_admin_review'].includes(norm(r.status))).length;
    const pendingAds=(D.campaigns||[]).filter(r=>['pending_review','pending','awaiting_approval'].includes(norm(r.status))).length;
    const telemetry=D.telemetry||{};
    const systemIssues=telemetry.systemIssues||{total:0,critical:0,error:0,warning:0};
    const paymentErrorCount=(D.paymentErrors||[]).filter(e=>!e.status||String(e.status).toLowerCase()==='unresolved').length;
    const alerts=[
      ['Unresponded Messages',M.unrespondedMessages(),'unresponded'],
      ['Property Reports (Unprocessed)',unprocessedReports,'complaints'],
      ['Pending Ad Approvals',pendingAds,'ads'],
      ['Fraud Detections',M.fraudCount(D.fraudFlags,enabledFraud),'fraud'],
      ['Payment Errors',paymentErrorCount,'payments'],
      ['Pending Agency Reviews',M.pendingAgencies(),'agents']
    ];
    const users=M.platformAccounts(),customerUsers=users.filter(a=>a.type==='Client'),agentUsers=users.filter(a=>a.type==='Agency');
    const currentMonth=M.monthStart(D.today),inquiryCreatedDate=q=>String(q.createdAt||'').slice(0,10),todayInquiryCount=(D.enquiries||[]).filter(q=>inquiryCreatedDate(q)===D.today).length,yesterdayInquiryCount=(D.enquiries||[]).filter(q=>inquiryCreatedDate(q)===U.addDays(D.today,-1)).length;
    const withdrawal=M.withdrawalStats(D.accounts,currentMonth,D.today);
    const delta=(a,b)=>b?((a-b)/b*100).toFixed(1)+'% vs previous day':'No previous-day baseline';
    const mockValue=(value,unit='')=>Number.isFinite(Number(value))?number(Number(value),unit):'—';
    const mockNote=label=>label+' · prototype telemetry only; production source is backend/API.';
    const statusBadge=item=>{const status=item?.status||'Not configured';const cls=/operational|healthy|ok/i.test(status)?'green':'amber';return '<b class="badge '+cls+'">'+esc(status)+'</b>';};
    const publishedCount=D.properties?.length?D.properties.filter(p=>(p.publishStatus||p.status)==='Published'&&!(p.endedAt||p.suspensionDate)).length:null;
    const graphs=['r28','r29','r30','r31','r32'].map(id=>S.metrics.find(s=>s.id===id));
    document.getElementById('mainContent').innerHTML=`
      <div class="section-heading"><h2>Operational alerts</h2><button class="btn" id="fraudSettings">Fraud KPI settings</button></div>
      <div class="cards six">${alerts.map(([label,count,key])=>`<button type="button" class="card alert-card ${['ads','agents'].includes(key)?'amber':'red'}" data-alert="${key}"><div class="metric-label">${label}</div><div class="metric-value">${count}</div><span class="muted">Review details →</span></button>`).join('')}</div>
      <div class="section-heading"><h2>System status</h2><span class="muted">Prototype telemetry · no backend health integration in this repository</span></div>
      <div class="status-strip">
        <span>API ${statusBadge(telemetry.api)}</span>
        <span>Database ${statusBadge(telemetry.database)}</span>
        <span>Stripe ${statusBadge(telemetry.paymentGateway)}</span>
        <span>System Issues · 24h <button class="btn" data-alert="logs">${Number(systemIssues.total)||0} →</button> <small>Critical ${Number(systemIssues.critical)||0} · Error ${Number(systemIssues.error)||0} · Warning ${Number(systemIssues.warning)||0}</small></span>
      </div>
      <div class="section-heading"><h2>Platform KPIs</h2><div class="inline-fields"><label>Account type <select id="kpiUserType"><option>All</option><option>Client</option><option>Agency</option></select></label><label>Active window <select id="kpiActiveWindow"><option value="1">DAU</option><option value="7">WAU</option><option value="30">MAU</option></select></label></div></div>
      <div class="cards">
        ${kcard('Total Users',users.length,'Excludes withdrawn accounts · '+customerUsers.length+' Clients / '+agentUsers.length+' Agencies')}
        ${kcard('Active Users','<span id="kpiActiveValue">'+M.activity(users,D.today,1)+'</span>','Registered accounts with recorded login/activity in selected window')}
        ${kcard('Avg Session Time',Number.isFinite(Number(telemetry.avgSessionSeconds))?mockValue(telemetry.avgSessionSeconds)+'s':'—',mockNote('Avg Session Time'))}
        ${kcard("Today's Revenue",mockValue(telemetry.todayRevenue,'JPY'),mockNote("Today's Revenue"))}
        ${kcard('MTD Revenue',mockValue(telemetry.mtdRevenue,'JPY'),mockNote('MTD Revenue'))}
        ${kcard('MRR','—','Requires Subscription Plan Master + active recurring payment/subscription records. Dashboard must not hard-code plan prices.')}
        ${kcard('Total Listed Properties',publishedCount==null?'—':publishedCount,publishedCount==null?'Requires operational/shared Property store.':'Published listings from persisted Property records only.')}
        ${kcard("Today's Inquiries",todayInquiryCount,delta(todayInquiryCount,yesterdayInquiryCount)+' · NEW Client → Agency property inquiries only; duplicate reopen does not increment')}
      </div>
      <div class="section-heading"><h2>Account changes this month</h2><span class="badge amber">Provisional · ${currentMonth} – ${D.today}</span></div>
      <div class="cards">
        ${kcard('Withdrawals this month',withdrawal.withdrawals,'Explicit account_status_changed → Withdrawn only. Suspend/Ban and inactivity are excluded.','red')}
      </div>
      <div class="section-heading"><h2>Targets and progress</h2><button class="btn" id="targetSettings">Set targets</button></div><div id="targetCards"></div>
      <div class="section-heading"><h2>Trends</h2><a href="end-user-stats-dashboard.html#metric-r56">View withdrawal history →</a></div><div class="chart-grid">${graphs.map(chartCard).join('')}</div>`;
    renderTargets();
    document.getElementById('fraudSettings').onclick=openFraudSettings;document.getElementById('targetSettings').onclick=openTargetSettings;
    const update=()=>{const type=document.getElementById('kpiUserType').value,days=Number(document.getElementById('kpiActiveWindow').value);document.getElementById('kpiActiveValue').textContent=M.activity(users.filter(a=>type==='All'||a.type===type),D.today,days);};
    document.getElementById('kpiUserType').onchange=update;document.getElementById('kpiActiveWindow').onchange=update;
  }
  function openDialog(title,html){const d=document.getElementById('overviewDialog');document.getElementById('dialogTitle').textContent=title;document.getElementById('dialogBody').innerHTML=html;d.showModal();}
  function openFraudSettings(){openDialog('Fraud KPI · alert inclusion',`<p class="muted">Count unique flags with status “unhandled” for enabled alert types. Turning an item off excludes it from this KPI; it does not disable detection or delete flags.</p><form id="fraudForm">${S.alerts.filter(a=>a.fraud).map(a=>`<label class="switch-row"><input type="checkbox" name="${a.id}" ${enabledFraud[a.id]?'checked':''}><span><strong>${esc(a.name)}</strong><p>${esc(a.trigger)}</p><p>${esc(a.target.replace(/\bAgent\b/g,'Agency'))}</p></span></label>`).join('')}<p class="muted">Other automated alerts are not classified as Fraud in the workbook.</p><button type="submit" class="btn primary">Save KPI settings</button></form>`);document.getElementById('fraudForm').onsubmit=e=>{e.preventDefault();S.alerts.filter(a=>a.fraud).forEach(a=>enabledFraud[a.id]=e.target.elements[a.id].checked);storage.set('fraudKpi',enabledFraud);document.getElementById('overviewDialog').close();renderKpi();toast('Fraud KPI settings saved.');};}
  function showAlert(type){
    if(type==='fraud'){const flags=D.fraudFlags.filter(f=>f.status==='unhandled'&&enabledFraud[f.alertId]);openDialog('Unhandled fraud flags',`<p class="muted">${flags.length} included flags. Review the flag; detection alone does not establish fraud.</p><div class="table-wrap"><table><thead><tr><th>Flag</th><th>Alert</th><th>Account</th><th>Detected</th></tr></thead><tbody>${flags.map(f=>`<tr><td>${esc(f.id)}</td><td>${esc(S.alerts.find(a=>a.id===f.alertId)?.name)}</td><td>${esc(f.account)}</td><td>${esc(f.detectedAt)}</td></tr>`).join('')}</tbody></table></div>`);return;}
    if(type==='payments'){const breakdown=M.paymentBreakdown(D.paymentErrors);openDialog('Payment Errors',`<p class="muted">Unique unresolved payment failures and chargebacks, grouped into the five agreed categories.</p>${V.table({rows:breakdown.map(r=>({label:r.category,count:r.count})),columns:[{key:'count',label:'Unresolved',unit:''}]})}<details open><summary>Error details</summary><div class="table-wrap"><table><thead><tr><th>ID</th><th>Category</th><th>Stripe code / reason</th><th>Status</th></tr></thead><tbody>${D.paymentErrors.filter(e=>e.status==='unresolved').map(e=>`<tr><td>${e.id}</td><td>${esc(e.category)}</td><td>${esc(e.code)}</td><td>${e.status}</td></tr>`).join('')}</tbody></table></div></details>`);return;}
    if(type==='logs'){const summary=M.systemIssueSummary(D.logs),logs=summary.issues;openDialog('System Issues · past 24 hours',`<div class="notice">Total ${summary.total} · Critical ${summary.critical} · Error ${summary.error} · Warning ${summary.warning}. User-input validation, minor frontend warnings, INFO and DEBUG events are excluded.</div><div class="table-wrap"><table><thead><tr><th>Occurred</th><th>Severity</th><th>Function / service</th><th>Identifier</th><th>Summary</th><th>Occurrences</th><th>Status</th></tr></thead><tbody>${logs.map(l=>`<tr><td>${esc(l.occurredAt||l.timestamp)}</td><td><span class="badge ${l.severity==='WARN'?'amber':'red'}">${l.severity==='FATAL'?'CRITICAL':esc(l.severity)}</span></td><td>${esc(l.affectedService||l.source)}</td><td>${esc(l.errorCode||l.id)}</td><td>${esc(l.summary||'System issue')}</td><td>${Number(l.occurrenceCount)||1}</td><td>${esc(l.status||'Open')}</td></tr>`).join('')}</tbody></table></div>`);return;}
    const destinations={unresponded:['Unresponded Messages','../messagesupport/admin-messages.html'],complaints:['Unprocessed Property Complaints','../property/property-report-management.html'],ads:['Pending Ad Approvals','../monetisation ads/05-booking-approvals.html'],agents:['Pending Agency Reviews','../usermanagement/agent-management.html']};const [title,url]=destinations[type];openDialog(title,`<p>Open the corresponding admin queue to review these items.</p><a class="btn primary" href="${esc(url)}">Open management page →</a>`);
  }
  const targetMetrics={totalRevenue:'Total revenue',subscription:'Subscription revenue',banner:'Sponsored banner revenue',sponsored:'Sponsored listing revenue',appraisal:'Appraisal referral revenue',optionRevenue:'Add-on / option revenue',users:'New users',subscriptions:'Active subscriptions',listings:'Published listings'};
  function targetActual(target){const rows=D.facts.filter(r=>M.inPeriod(r.date,target.start,target.end));if(target.metric==='totalRevenue')return rows.reduce((n,r)=>n+M.amount(r),0);if(target.metric==='users')return M.platformAccounts(D.accounts,target.end).filter(a=>M.inPeriod(a.registeredAt,target.start,target.end)).length;if(target.metric==='subscriptions')return M.activeSubscriptions(target.end).length;if(target.metric==='listings')return D.properties.filter(p=>p.createdAt<=target.end&&(!p.endedAt||p.endedAt>target.end)).length;return M.sum(rows,target.metric);}
  function renderTargets(){const holder=document.getElementById('targetCards');if(!holder)return;holder.innerHTML=targets.length?`<div class="cards">${targets.map(t=>{const actual=targetActual(t),pct=M.ratio(actual,t.value);return `<div class="card"><div class="metric-label">${esc(targetMetrics[t.metric])}</div><div class="metric-value">${number(pct)}%</div><div class="target-progress"><span style="width:${Math.min(100,pct)}%"></span></div><div class="muted">${number(actual)} / ${number(t.value)} · ${esc(t.start)} – ${esc(t.end)}</div></div>`;}).join('')}</div>`:'<div class="notice">No targets configured. Set a metric, target value and period to track progress.</div>';}
  function openTargetSettings(){openDialog('Target setting',`<p class="muted">Set independent periods for total/category revenue, users, subscriptions and property listings.</p><form id="targetForm" class="targets-form">${select('targetMetric','Target Metric',Object.entries(targetMetrics))}<label class="field">Start Date<input id="targetStart" type="date" required></label><label class="field">End Date<input id="targetEnd" type="date" required></label><label class="field">Target Value<input id="targetValue" type="number" required min="1" step="1"></label><button class="btn primary">Add target</button></form><div id="savedTargets">${targets.map((t,i)=>`<p class="muted">${esc(targetMetrics[t.metric])} · ${number(t.value)} · ${t.start} – ${t.end} <button class="btn" data-delete-target="${i}">Remove</button></p>`).join('')}</div>`);const valueInput=document.getElementById('targetValue');const updateTargetValue=()=>{const count=['users','subscriptions','listings'].includes(document.getElementById('targetMetric').value);valueInput.step=count?'1':'any';valueInput.min=count?'1':'0';};document.getElementById('targetMetric').onchange=updateTargetValue;updateTargetValue();document.getElementById('targetStart').value=M.monthStart(D.today);document.getElementById('targetEnd').value=U.addDays(M.shiftMonth(M.monthStart(D.today),1),-1);document.getElementById('targetForm').onsubmit=event=>{event.preventDefault();const t={metric:document.getElementById('targetMetric').value,value:Number(document.getElementById('targetValue').value),start:document.getElementById('targetStart').value,end:document.getElementById('targetEnd').value};if(!M.validateTarget(t)){toast('Enter valid required dates (End Date ≥ Start Date) and a positive finite target; count metrics require whole numbers.');return;}targets.push(t);storage.set('targets',targets);renderTargets();document.getElementById('overviewDialog').close();toast('Target saved.');};}
  const reportTypes={market:'Monthly Market Report',revenue:'Revenue Report',users:'User Report',withdrawalReasons:'Withdrawal Reason Analysis',operations:'Operational Report',reportReasons:'Property Report Reason Analysis',anonymized:'Data Monetization Report'};
  function reportData(type){const rows=M.filteredFacts(filters),users=M.filteredAccounts(filters);if(type==='market'||type==='anonymized'){const properties=new Map(D.properties.map(p=>[p.id,p]));return M.result(M.groupBy(rows,r=>r.date.slice(0,7)+' · '+properties.get(r.propertyId).prefecture+' · '+properties.get(r.propertyId).transaction+' · '+properties.get(r.propertyId).subtype,items=>{const ps=[...new Set(items.map(r=>r.propertyId))].map(id=>properties.get(id));return {price:M.average(ps,'price'),closingPrice:M.average(ps,'closingPrice'),listings:ps.length,deals:M.sum(items,'deals')};}),['price','closingPrice','listings','deals'],'table',type==='anonymized'?'Aggregated market data only. No account IDs, names, contact details, IPs or exact addresses are exported.':'Market-only report. Revenue is reported separately.');}
    if(type==='revenue'){
      const categories={subscription:'Subscription',banner:'Banner',sponsored:'Sponsored listing',featured:'Featured listing',appraisal:'Appraisal referral',optionRevenue:'Option purchases'};
      const segment=(r,key)=>key==='subscription'?D.agents.find(a=>a.id===r.agentId).plan:key==='banner'?r.placement:key==='optionRevenue'?r.option:'All';
      const previousRows=M.filteredFacts({...filters,start:M.shiftMonth(filters.start,-1),end:M.shiftMonth(filters.end,-1)});
      const output=M.buckets(filters.start,filters.end,'Monthly').flatMap(b=>Object.entries(categories).flatMap(([key,label])=>{
        const current=rows.filter(r=>M.inPeriod(r.date,b.start,b.end)),previous=previousRows.filter(r=>M.inPeriod(r.date,M.shiftMonth(b.start,-1),M.shiftMonth(b.end,-1)));
        return [...new Set([...current,...previous].filter(r=>r[key]>0).map(r=>segment(r,key)))].map(name=>{const revenue=M.sum(current.filter(r=>segment(r,key)===name),key),previousRevenue=M.sum(previous.filter(r=>segment(r,key)===name),key);return {label:b.label+' · '+label+' · '+name,revenue,previousRevenue,mom:previousRevenue?(revenue-previousRevenue)/previousRevenue*100:null};});
      }));
      return M.result(output,['revenue','previousRevenue','mom'],'table','Completed payments by category; subscriptions by tier, banners by placement and options by product. Month-on-month compares the same selected date range in the prior month.');
    }
    if(type==='withdrawalReasons'){
      const events=(D.analyticsEvents||[]).filter(e=>e.type==='account_status_changed'&&e.newStatus==='Withdrawn');
      const rows=[];
      for(const accountType of ['Customer','Agency','Supportal']){
        const master=window.YuushiAnalytics?.masters.withdrawalReasons?.[accountType]||[];
        for(const [code,label] of master){
          const count=events.filter(e=>e.accountType===accountType&&e.withdrawalReasonCode===code&&M.inPeriod((e.withdrawnAt||e.occurredAt||'').slice(0,10),filters.start,filters.end)).length;
          rows.push({label:accountType+' · '+label,accountType,code,count});
        }
      }
      return M.result(rows,['count'],'table','Canonical JHN withdrawal reasons only. Suspend/Ban and inactivity are excluded; Other detail remains free text and is not promoted to a new category.');
    }
    if(type==='reportReasons'){
      const reportLabels=new Map((window.YuushiAnalytics?.masters.reportReasons||[]).map(([code,label])=>[code,label]));
      const dismissLabels=new Map((window.YuushiAnalytics?.masters.reportDismissReasons||[]).map(([code,label])=>[code,label]));
      const rows=[];
      for(const [code,label] of reportLabels){
        const count=(D.reports||[]).filter(r=>r.reason===code).length;
        rows.push({label:'Report Reason · '+label,taxonomy:'Report Reason',code,count});
      }
      for(const [code,label] of dismissLabels){
        const count=(D.reports||[]).filter(r=>r.status==='dismissed'&&r.dismissReason===code).length;
        rows.push({label:'Dismiss Reason · '+label,taxonomy:'Dismiss Reason',code,count});
      }
      return M.result(rows,['count'],'table','Report Reason uses the Customer/Admin C07 reason enum. Dismiss Reason is a separate Admin decision taxonomy; the two are never merged.');
    }
    if(type==='users'){
      const allAccounts=D.accounts||[],withdrawEvents=(D.analyticsEvents||[]).filter(e=>e.type==='account_status_changed'&&e.newStatus==='Withdrawn');
      return M.result(M.buckets(filters.start,filters.end,filters.unit).flatMap(b=>['Client','Agency'].map(accountType=>{
        const pool=allAccounts.filter(a=>a.type===accountType);
        const withdrawals=new Set(withdrawEvents.filter(e=>e.accountType===accountType&&M.inPeriod((e.withdrawnAt||e.occurredAt||'').slice(0,10),b.start,b.end)).map(e=>e.eventId||[e.accountId,e.occurredAt].join('|'))).size;
        const newUsers=pool.filter(a=>a.registeredAt&&M.inPeriod(String(a.registeredAt).slice(0,10),b.start,b.end)).length;
        const activeAtEnd=pool.filter(a=>a.registeredAt&&String(a.registeredAt).slice(0,10)<=b.end&&(!a.withdrawnAt||String(a.withdrawnAt).slice(0,10)>b.end)).length;
        const sessionEvents=(D.analyticsEvents||[]).filter(e=>e.type==='session_started'&&e.accountType===accountType&&e.accountId);
        const inactive=pool.filter(a=>{
          if(!a.registeredAt||(a.withdrawnAt&&String(a.withdrawnAt).slice(0,10)<=b.end))return false;
          const accountId=a.id||a.customerId||a.agencyId;
          const last=sessionEvents.filter(e=>String(e.accountId)===String(accountId)&&String(e.occurredAt).slice(0,10)<=b.end).sort((x,y)=>String(y.occurredAt).localeCompare(String(x.occurredAt)))[0];
          const baseline=last?String(last.occurredAt).slice(0,10):String(a.registeredAt).slice(0,10);
          return (Date.parse(b.end)-Date.parse(baseline))/86400000>=30;
        }).length;
        return {label:b.label+' · '+accountType,total:activeAtEnd,registrations:newUsers,inactive,withdrawals,netGrowth:newUsers-withdrawals};
      })),['total','registrations','inactive','withdrawals','netGrowth'],'table','Withdrawals use account_status_changed events. "Inactive" is an analytics segment (30+ days without a recorded session), not Withdrawn/Dormant status.');
    }
    const unresolvedReports=(D.reports||[]).filter(r=>['awaiting_agency_response','pending_admin_review'].includes(String(r.status||'').trim().toLowerCase().replace(/\s+/g,'_'))).length;
    const pendingAds=(D.campaigns||[]).filter(r=>['pending review','pending','awaiting approval'].includes(String(r.status||'').trim().toLowerCase())).length;
    return M.result([
      {label:'Unresponded Messages',count:M.unrespondedMessages()},
      {label:'Property Reports (Unprocessed)',count:unresolvedReports},
      {label:'Pending Ad Approvals',count:pendingAds},
      {label:'Fraud Detections',count:M.fraudCount(D.fraudFlags,enabledFraud)},
      {label:'Payment Errors',count:M.sum(M.paymentBreakdown(D.paymentErrors),'count')},
      {label:'Pending Agency Reviews',count:M.pendingAgencies()}
    ],['count'],'table','Current operational queue snapshot. No literal/demo queue counts are used.');
  }
  const builderAxes={month:'Month',date:'Date',prefecture:'Prefecture',city:'City / Ward',transaction:'Transaction type',group:'Property group',subtype:'Property sub-type',station:'Station',line:'Railway line',structure:'Building structure',floorPlan:'Floor plan',member:'Member / Non-member',country:'Country',section:'Content section',adType:'Ad type',placement:'Ad placement'};
  const builderMeasures={impressions:'Impressions',clicks:'Clicks',saves:'Saves',inquiries:'Inquiries',deals:'Deals',sessions:'Sessions',searches:'Searches',ctr:'CTR (%)',cvr:'CVR (%)',revenue:'Total revenue (JPY)',subscription:'Subscription revenue (JPY)',banner:'Banner revenue (JPY)',sponsored:'Sponsored listing revenue (JPY)',appraisal:'Appraisal referral revenue (JPY)',optionRevenue:'Option revenue (JPY)'};
  function customReport(){const axes=[...document.getElementById('builderAxes').selectedOptions].map(o=>o.value),measures=[...document.getElementById('builderMeasures').selectedOptions].map(o=>o.value);if(!axes.length||!measures.length){toast('Select at least one dimension and one metric.');return null;}const props=new Map(D.properties.map(p=>[p.id,p]));const grouped=M.groupBy(M.filteredFacts(filters),r=>axes.map(key=>key==='month'?r.date.slice(0,7):key==='member'?r.member?'Members':'Non-Members':r[key]??props.get(r.propertyId)[key]).join(' · '),items=>({...M.performance(items),revenue:items.reduce((n,r)=>n+M.amount(r),0),...Object.fromEntries(measures.filter(k=>!['ctr','cvr','revenue'].includes(k)).map(k=>[k,M.sum(items,k)]))}));return {data:M.result(grouped,measures,'table'),axes,measures};}
  function reportReasonBreakdowns(){
    const reportLabels=new Map((window.YuushiAnalytics?.masters.reportReasons||[]).map(([code,label])=>[code,label]));
    const dismissLabels=new Map((window.YuushiAnalytics?.masters.reportDismissReasons||[]).map(([code,label])=>[code,label]));
    const reports=D.reports||[];
    const countBy=(rows,key,labels)=>[...labels].map(([code,label])=>({label,count:rows.filter(r=>r[key]===code).length})).filter(r=>r.count>0);
    return {
      reportReasons:M.result(countBy(reports,'reason',reportLabels),['count'],'bar','Counts from the Customer/Agency Property Report reason enum.'),
      dismissReasons:M.result(countBy(reports.filter(r=>r.status==='dismissed'),'dismissReason',dismissLabels),['count'],'bar','Dismissed reports only, grouped by the Admin Dismiss Reason taxonomy.')
    };
  }
  function renderReports(){results.clear();document.getElementById('filterSummary').textContent=filters.start+' – '+filters.end+' · report filters retained across pages';const types=page==='financial'?['revenue']:page==='sales'?['market','anonymized']:Object.keys(reportTypes);document.getElementById('mainContent').innerHTML=`<div class="section-heading"><h2>Standard reports</h2><span class="muted">Data generated from the selected period</span></div><div class="report-grid">${types.map(type=>{const r=reportData(type);results.set('report-'+type,r);return `<article class="card report-card"><h3>${reportTypes[type]}</h3><p>${esc(r.note||({users:'Accounts, registrations, inactivity, withdrawals and net growth.',revenue:'Revenue by subscription tier, category and banner placement.'}[type]||''))}</p><p>${r.rows.length} rows · ${filters.start} – ${filters.end}</p><div class="actions"><button class="btn" data-preview-report="${type}">View report</button><button class="btn primary" data-export="report-${type}">Export</button>${type==='market'?'<button class="btn" data-print-report="market">Print / PDF</button>':''}</div></article>`;}).join('')}</div>${page==='reports'?(()=>{const b=reportReasonBreakdowns();results.set('report-reason-breakdown',b.reportReasons);results.set('dismiss-reason-breakdown',b.dismissReasons);return `<div class="section-heading"><h2>Property report reason breakdowns</h2><span class="muted">Operational C07 records only</span></div><div class="chart-grid"><article class="card chart-card"><h3>Reports by Report Reason</h3><div class="chart-wrap">${V.render(b.reportReasons)}</div><div class="chart-footer"><span></span><button class="btn" data-export="report-reason-breakdown">Export</button></div></article><article class="card chart-card"><h3>Dismissed Reports by Dismiss Reason</h3><div class="chart-wrap">${V.render(b.dismissReasons)}</div><div class="chart-footer"><span></span><button class="btn" data-export="dismiss-reason-breakdown">Export</button></div></article></div>`;})():''}<div class="section-heading"><h2>Custom report builder</h2></div><div class="card"><div class="filter-grid">${select('builderAxes','Dimensions',Object.entries(builderAxes),true)}${select('builderMeasures','Metrics',Object.entries(builderMeasures),true)}<div><label class="field">Shortcut name<input id="shortcutName" placeholder="e.g. Monthly Tokyo property report"></label><div class="actions" style="margin-top:12px"><button class="btn primary" id="buildReport">Build report</button><button class="btn" id="saveShortcut">Save shortcut</button></div><p class="muted">Uses the common filters above. Dimensions and metrics can be combined in one CSV.</p></div></div><div id="customReportOutput"></div><div class="actions" id="shortcuts">${savedReports.map((r,i)=>`<button class="btn" data-shortcut="${i}">${esc(r.name)}</button><button class="btn" data-delete-shortcut="${i}" aria-label="Delete ${esc(r.name)}">×</button>`).join('')}</div></div><div class="section-heading"><h2>Scheduled report delivery</h2></div><div class="card"><p class="notice">Choose the report, delivery frequency, time and recipients.</p><form id="scheduleForm"><div class="filter-primary">${select('scheduleType','Report',Object.entries(reportTypes))}${select('scheduleFrequency','Frequency',['Daily','Weekly','Monthly'])}${input('scheduleTime','Delivery time (JST)','time')}<label class="field">Recipient emails<input type="email" id="scheduleRecipients" multiple required placeholder="team@example.com, manager@example.com"></label></div><button class="btn primary">Save schedule</button></form><div id="scheduleList"></div></div><div class="section-heading"><h2>Monthly market snapshot</h2></div><div class="notice">The previous completed month is generated automatically when this page opens. <button class="btn" id="monthlySnapshot">Download latest completed month</button></div>`;
    document.getElementById('builderAxes').options[0].selected=true;document.getElementById('builderMeasures').options[0].selected=true;document.getElementById('scheduleTime').value='09:00';
    document.getElementById('buildReport').onclick=()=>{const r=customReport();if(r){results.set('custom',r.data);document.getElementById('customReportOutput').innerHTML=V.table(r.data)+'<button class="btn primary" data-export="custom">Export custom report</button>';}};
    document.getElementById('saveShortcut').onclick=()=>{const r=customReport(),name=document.getElementById('shortcutName').value.trim();if(!r||!name){toast('Name the shortcut before saving.');return;}savedReports.push({name,axes:r.axes,measures:r.measures,filters:{...filters}});storage.set('reportShortcuts',savedReports);renderReports();toast('Report shortcut saved.');};
    document.getElementById('scheduleForm').onsubmit=e=>{e.preventDefault();schedules.push({id:Date.now(),report:document.getElementById('scheduleType').value,frequency:document.getElementById('scheduleFrequency').value,filters:{...filters},time:document.getElementById('scheduleTime').value,recipients:document.getElementById('scheduleRecipients').value.split(',').map(s=>s.trim()).filter(Boolean)});storage.set('reportSchedules',schedules);renderScheduleList();toast('Schedule saved.');};renderScheduleList();
    const old={...filters},end=U.addDays(M.monthStart(D.today),-1);filters={...defaults,start:M.monthStart(end),end,unit:'Monthly'};const snapshot=reportData('market');filters=old;storage.set('latestMonthlyMarketSnapshot',{month:end.slice(0,7),generatedAt:new Date().toISOString(),...snapshot});document.getElementById('monthlySnapshot').onclick=()=>downloadCSV('monthly-market-'+end.slice(0,7)+'.csv',[{key:'label',label:'Period / Segment'},...snapshot.columns],snapshot.rows);
  }
  function renderScheduleList(){document.getElementById('scheduleList').innerHTML=schedules.length?`<div class="table-wrap"><table><thead><tr><th>Report</th><th>Frequency</th><th>Time (JST)</th><th>Recipients</th><th>Status</th><th></th></tr></thead><tbody>${schedules.map((s,i)=>`<tr><td>${esc(reportTypes[s.report])}</td><td>${esc(s.frequency)}</td><td>${esc(s.time)}</td><td>${esc(s.recipients.join(', '))}</td><td>Saved</td><td><button class="btn" data-delete-schedule="${i}">Remove</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No schedules configured.</p>';}
  function render(){if(page==='kpi')renderKpi();else if(['reports','financial','sales'].includes(page))renderReports();else renderAnalytics();}
  document.getElementById('overviewApp').innerHTML=`<div class="overview-shell"><header class="page-header"><div><div class="eyebrow">YUUSHI · Admin Overview</div><h1>${esc(pages[page][0])}</h1><p class="subtitle">${new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Tokyo',dateStyle:'medium',timeStyle:'short'}).format(new Date())} JST</p></div><div class="actions"><button class="btn" id="exportPage">Export page CSV</button><button class="btn primary" id="refreshPage">Refresh</button></div></header>${page==='kpi'?'':filterMarkup()}<main id="mainContent"></main><dialog id="overviewDialog" aria-labelledby="dialogTitle"><div class="dialog-title"><h2 id="dialogTitle"></h2><button class="close-button" id="closeDialog" aria-label="Close">×</button></div><div id="dialogBody"></div></dialog><div class="toast" id="toast" role="status" hidden></div></div>`;
  if(page!=='kpi'){
    restoreFilters();
    for(const id of ['transaction','groups','prefectures','line','comparison'])document.getElementById(id).addEventListener('change',updateDependentFilters);
    document.getElementById('overviewFilters').onsubmit=e=>{e.preventDefault();const next=readFilters(),error=validateFilters(next);const errorEl=document.getElementById('filterError');errorEl.hidden=!error;errorEl.textContent=error;if(error)return;filtersApplied=true;filters=next;storage.set('filters',filters);render();};
    document.getElementById('resetFilters').onclick=()=>{filtersApplied=false;filters={...defaults};storage.set('filters',filters);restoreFilters();render();};
  }
  document.getElementById('refreshPage').onclick=()=>{render();toast('Figures updated.');};
  document.getElementById('exportPage').onclick=()=>{const rows=[...results].flatMap(([metric,r])=>r.rows.flatMap(row=>r.columns.map(c=>({metric,segment:row.label,measure:c.label,value:row[c.key],unit:c.unit}))));downloadCSV(page+'-'+D.today+'.csv',[{key:'metric',label:'Metric'},{key:'segment',label:'Period / Segment'},{key:'measure',label:'Measure'},{key:'value',label:'Value'},{key:'unit',label:'Unit'}],rows);};
  document.getElementById('closeDialog').onclick=()=>document.getElementById('overviewDialog').close();
  document.getElementById('overviewDialog').addEventListener('click',e=>{if(e.target===e.currentTarget)e.currentTarget.close();});
  document.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;
    if(button.dataset.export)exportResult(button.dataset.export);
    if(button.dataset.alert)showAlert(button.dataset.alert);
    if(button.dataset.sort){const table=button.closest('table'),body=table.tBodies[0],column=Number(button.dataset.sortColumn),direction=button.dataset.direction==='desc'?'asc':'desc';button.dataset.direction=direction;[...body.rows].sort((a,b)=>{const av=a.cells[column].dataset.value,bv=b.cells[column].dataset.value;if(av==='')return bv===''?0:1;if(bv==='')return -1;return (Number(av)-Number(bv))*(direction==='asc'?1:-1);}).forEach(row=>body.appendChild(row));}
    if(button.dataset.previewReport){const r=results.get('report-'+button.dataset.previewReport);openDialog(reportTypes[button.dataset.previewReport],V.table(r));}
    if(button.dataset.printReport){const r=results.get('report-'+button.dataset.printReport);openDialog(reportTypes[button.dataset.printReport],V.table(r));document.body.classList.add('printing-report');window.print();document.body.classList.remove('printing-report');}
    if(button.dataset.deleteTarget!==undefined){targets.splice(Number(button.dataset.deleteTarget),1);storage.set('targets',targets);renderTargets();document.getElementById('overviewDialog').close();openTargetSettings();}
    if(button.dataset.deleteSchedule!==undefined){schedules.splice(Number(button.dataset.deleteSchedule),1);storage.set('reportSchedules',schedules);renderScheduleList();}
    if(button.dataset.deleteShortcut!==undefined){savedReports.splice(Number(button.dataset.deleteShortcut),1);storage.set('reportShortcuts',savedReports);renderReports();}
    if(button.dataset.shortcut!==undefined){const shortcut=savedReports[Number(button.dataset.shortcut)];filters={...defaults,...shortcut.filters};storage.set('filters',filters);restoreFilters();renderReports();for(const [id,keys] of [['builderAxes',shortcut.axes],['builderMeasures',shortcut.measures]])[...document.getElementById(id).options].forEach(o=>o.selected=keys.includes(o.value));document.getElementById('buildReport').click();}
  });
  document.addEventListener('change',e=>{if(e.target.dataset.series){const id=e.target.dataset.series,series=choices.get(id)?.series||['sessions','clicks','saves','inquiries','deals'];choices.set(id,{...choices.get(id),series:e.target.checked?[...new Set([...series,e.target.value])]:series.filter(key=>key!==e.target.value),measure:''});document.getElementById('metric-'+id).outerHTML=chartCard(S.metrics.find(s=>s.id===id));return;}const id=e.target.dataset.measure||e.target.dataset.breakdown||e.target.dataset.rankBy;if(!id)return;choices.set(id,{...choices.get(id),[e.target.dataset.measure?'measure':e.target.dataset.rankBy?'rankBy':'breakdown']:e.target.value});const spec=S.metrics.find(s=>s.id===id);const old=document.getElementById('metric-'+id);if(old)old.outerHTML=chartCard(spec);});
  render();
  if(window.parent && window.parent!==window){try{const target='overview/'+pages[page][1];window.parent.document.querySelectorAll('.menu-item[data-content]').forEach(link=>link.classList.toggle('active',link.dataset.content===target));}catch{}}
  if(location.hash)requestAnimationFrame(()=>document.getElementById(location.hash.slice(1))?.scrollIntoView());
})();
